import {palette} from './palette';
new Phaser.Game({type:Phaser.CANVAS,canvas:game.canvas,parent:game.root,width:800,height:600,backgroundColor:palette.background,scale:{mode:Phaser.Scale.FIT,autoCenter:Phaser.Scale.CENTER_BOTH},scene:{create(){
 this.input.keyboard.removeAllListeners();
 let score=0, remaining=30;
 this.add.text(32,24,'Acchiappa la stella',{fontSize:'30px',color:'#ffffff'});
 this.add.text(32,68,'Tocca la stella o premi Spazio. Hai 30 secondi!',{fontSize:'18px'});
 const hud=this.add.text(32,110,'Punti: 0 · Tempo: 30',{fontSize:'22px'});
 const star=this.add.star(400,300,5,24,52,0xffd166).setInteractive({useHandCursor:true});
 const collect=()=>{if(remaining<=0)return;score++;star.setPosition(Phaser.Math.Between(70,730),Phaser.Math.Between(200,510));hud.setText(`Punti: ${score} · Tempo: ${remaining}`)};star.on('pointerdown',collect);this.input.keyboard.on('keydown-SPACE',collect);
 this.time.addEvent({delay:1000,repeat:29,callback:()=>{remaining--;hud.setText(`Punti: ${score} · Tempo: ${remaining}`);if(!remaining){star.disableInteractive();this.add.text(200,530,'Fine! Tocca qui per rigiocare',{fontSize:'24px'}).setInteractive({useHandCursor:true}).on('pointerdown',()=>this.scene.restart());this.input.keyboard.once('keydown-R',()=>this.scene.restart())}}});
}}});
